import{z as n,x as i,o as e,c as o,q as r,j as m,D as A,d as a,s as t,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"失败模式与收束","description":"","frontmatter":{"title":"失败模式与收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-map.md","filePath":"llm/mm-map.md","lastUpdated":1791413859000}'),p={name:"llm/mm-map.md"};function F(d,E,C,D,h,f){const l=i("Mermaid");return e(),o("div",null,[E[2]||(E[2]=r('<h1 id="失败模式与收束" tabindex="-1">失败模式与收束 <a class="header-anchor" href="#失败模式与收束" aria-label="Permalink to &quot;失败模式与收束&quot;">​</a></h1><div class="epigraph"><p>多模态服务的病很少喊疼：不报错，只变笨；收束的办法是把「变笨」钉回哪一族、出自哪一课。</p><footer>—— 据本课程前十一课的失败条款与推理系统排障实践整理</footer></div><p><a href="/llm/mm-cost-capacity">上一课</a>把整条栈折成成本账与容量梯子。至此课程走完一条线：<a href="/llm/mm-serving-vision-encoder">编码器池</a>、<a href="/llm/mm-image-preprocess-batching">预处理</a>、<a href="/llm/mm-visual-token-budget">视觉预算</a>、<a href="/llm/mm-video-serving">视频</a>与<a href="/llm/mm-speech-serving">语音</a>、<a href="/llm/mm-multimodal-kv">KV 管理</a>、<a href="/llm/mm-multimodal-speculative">投机</a>、<a href="/llm/mm-edge-multimodal">边缘</a>、<a href="/llm/mm-eval-serving">评测</a>、<a href="/llm/mm-safety-filtering">过滤</a>与<a href="/llm/mm-cost-capacity">成本</a>。本课把全线失败条款收成族，给运维一张归因坐标，然后收束。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多模态服务的失败有个共同脾气：<strong>静默</strong>。文本服务的失败常以报错或明显胡言出现，多模态的失败更常表现为能力悄悄变差——图看不准了、话接不上了、账单变贵了——且只在部分请求上复现。原因在前十一课里反复出现：管线变长，模态间合同变多，而合同违约不会抛异常。把失败条款归族，「变笨」才能变成可排障的事件，而不是「模型最近状态不好」的玄学。</p><p><span class="marginnote">「静默失败」可以类比高血压：不疼不痒，但器官在悄悄受损——等服务「喊疼」（用户投诉、报错）时，坏请求已经积累了一大堆。所以多模态服务必须靠主动监测和归因坐标找病，不能等报错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>六族坐标，每族给信号与第一诊断动作。</p><p><strong>表示漂移族</strong>：预处理库、编码器、对话模板任一升级而缓存键没跟上，新旧嵌入与 KV 混用。信号：能力缓慢退化、命中率反常地高。第一动作：核对<a href="/llm/mm-image-preprocess-batching">缓存键版本</a>，清缓存对照。</p><p><strong>预算失衡族</strong>：视觉 token 超卖打穿窗口与 KV，或压得过低逼模型用语言先验补图。信号：长请求 TTFT 抬升、幻觉率上翘。第一动作：拉<a href="/llm/mm-visual-token-budget">预算回执</a>分布。</p><p><strong>资源错配族</strong>：编码与 prefill 混池互抢、CPU 饿死 GPU、大批发里投机亏本。信号：某段饱和而端到端吞吐不动。第一动作：按<a href="/llm/mm-serving-vision-encoder">分层利用率</a>找最紧一段。</p><p><strong>时序违约族</strong>：视频时间戳丢失、<a href="/llm/mm-speech-serving">语音端点与打断</a>丢上下文、流式挂起窗口错配。信号：定位类问答静默答错、对话答非所问。第一动作：回放中间产物，对时间合同逐条核。</p><p><strong>防线盲区族</strong>：图内文本绕过文本审核、审核分辨率低于主模型档、误杀无申诉通道。信号：红队样例穿透、投诉分流异常。第一动作：用<a href="/llm/mm-safety-filtering">合流审核</a>回归集重放。</p><p><span class="marginnote">「命中率反常地高」为什么是病征？缓存本该在内容变化后失效重算；旧嵌入还能命中，说明缓存键没跟上版本——就像换了锁芯之后旧钥匙还能开门，门没坏，是锁装错了。</span></p><p><strong>口径漂移族</strong>：评测不钉缓存与预算、成本模型随模型换代过期、纯文本压测给出假容量。信号：离线数字与线上体感背离。第一动作：按<a href="/llm/mm-eval-serving">四钉协议</a>重测对照。</p>',15)),(e(),m(s,null,{default:A(()=>[t(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E7%8E%B0%E8%B1%A1%EF%BC%9A%E8%83%BD%E5%8A%9B%E5%8F%98%E7%AC%A8%E6%88%96%E8%B4%A6%E5%8D%95%E5%8F%98%E8%B4%B5%22%5D%20--%3E%20TRI%7B%22%E4%B8%89%E8%B7%91%E5%88%A4%E6%8D%AE%22%7D%0A%20%20TRI%20--%3E%7C%22%E5%86%B7%E7%BC%93%E5%AD%98%2F%E7%83%AD%E7%BC%93%E5%AD%98%2F%E6%8D%A2%E6%A1%A3%E9%A2%84%E7%AE%97%20%E7%BB%93%E6%9E%9C%E4%B8%8D%E4%B8%80%E8%87%B4%22%7C%20ENV%5B%22%E7%8E%AF%E5%A2%83%E7%97%85%EF%BC%9A%E6%9F%A5%E6%BC%82%E7%A7%BB%E4%B8%8E%E8%B5%84%E6%BA%90%E6%97%8F%22%5D%0A%20%20TRI%20--%3E%7C%22%E4%B8%89%E6%AC%A1%E4%B8%80%E8%87%B4%22%7C%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E7%97%85%EF%BC%9A%E6%9F%A5%E9%A2%84%E7%AE%97%E4%B8%8E%E8%AF%84%E6%B5%8B%E5%8F%A3%E5%BE%84%22%5D%0A%20%20ENV%20--%3E%20F1%5B%22%E8%A1%A8%E7%A4%BA%E6%BC%82%E7%A7%BB%2F%E8%B5%84%E6%BA%90%E9%94%99%E9%85%8D%2F%E9%98%B2%E7%BA%BF%E7%9B%B2%E5%8C%BA%22%5D%0A%20%20MODEL%20--%3E%20F2%5B%22%E9%A2%84%E7%AE%97%E5%A4%B1%E8%A1%A1%2F%E6%97%B6%E5%BA%8F%E8%BF%9D%E7%BA%A6%2F%E5%8F%A3%E5%BE%84%E6%BC%82%E7%A7%BB%22%5D%0A%20%20F1%20--%3E%20FIX%5B%22%E6%8C%89%E6%97%8F%E7%AC%AC%E4%B8%80%E8%AF%8A%E6%96%AD%E5%8A%A8%E4%BD%9C%E5%A4%84%E7%90%86%22%5D%0A%20%20F2%20--%3E%20FIX%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("归因的枢纽是"),B("strong",null,"三跑判据"),a("：同一请求分别以冷缓存、热缓存、另一档预算跑三次。结果不一致，病在环境——缓存、版本、资源调度；三次一致，病才在模型或配置。这是"),B("a",{href:"/llm/pl-map"},"推理链课程"),a("「加预算恢复率」判据的多模态版：不猜病因，先花三次请求把环境与模型切开。六族在此框架下才有意义——族是归因坐标，不是互斥判决，一次事故常是两族复合。")],-1)),E[5]||(E[5]=B("p",null,"各族的监测面建在族上而不是指标上：漂移族盯缓存键版本对账，预算族盯回执分布，错配族盯分层利用率，时序族盯合同字段完整性，盲区族盯红队回归通过率，口径族盯离线与线上分数差。面板按族排布，告警才能直接落到第一诊断动作。",-1)),(e(),m(s,null,{default:A(()=>[t(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20F1%5B%22%E8%A1%A8%E7%A4%BA%E6%BC%82%E7%A7%BB%E6%97%8F%22%5D%20--%3E%7C%22%E5%91%BD%E4%B8%AD%E7%8E%87%E5%8F%8D%E5%B8%B8%E5%9C%B0%E9%AB%98%22%7C%20A1%5B%22%E6%A0%B8%E5%AF%B9%E7%BC%93%E5%AD%98%E9%94%AE%E7%89%88%E6%9C%AC%EF%BC%8C%E6%B8%85%E7%BC%93%E5%AD%98%E5%AF%B9%E7%85%A7%22%5D%0A%20%20F2%5B%22%E9%A2%84%E7%AE%97%E5%A4%B1%E8%A1%A1%E6%97%8F%22%5D%20--%3E%7C%22TTFT%20%E6%8A%AC%E5%8D%87%E3%80%81%E5%B9%BB%E8%A7%89%E4%B8%8A%E7%BF%98%22%7C%20A2%5B%22%E6%8B%89%E9%A2%84%E7%AE%97%E5%9B%9E%E6%89%A7%E5%88%86%E5%B8%83%22%5D%0A%20%20F3%5B%22%E8%B5%84%E6%BA%90%E9%94%99%E9%85%8D%E6%97%8F%22%5D%20--%3E%7C%22%E6%9F%90%E6%AE%B5%E9%A5%B1%E5%92%8C%E8%80%8C%E5%90%9E%E5%90%90%E4%B8%8D%E5%8A%A8%22%7C%20A3%5B%22%E6%8C%89%E5%88%86%E5%B1%82%E5%88%A9%E7%94%A8%E7%8E%87%E6%89%BE%E6%9C%80%E7%B4%A7%E4%B8%80%E6%AE%B5%22%5D%0A%20%20F4%5B%22%E6%97%B6%E5%BA%8F%E8%BF%9D%E7%BA%A6%E6%97%8F%22%5D%20--%3E%7C%22%E5%AE%9A%E4%BD%8D%E7%B1%BB%E9%97%AE%E7%AD%94%E9%9D%99%E9%BB%98%E7%AD%94%E9%94%99%22%7C%20A4%5B%22%E5%9B%9E%E6%94%BE%E4%B8%AD%E9%97%B4%E4%BA%A7%E7%89%A9%E6%A0%B8%E5%AF%B9%E6%97%B6%E9%97%B4%E5%90%88%E5%90%8C%22%5D%0A%20%20F5%5B%22%E9%98%B2%E7%BA%BF%E7%9B%B2%E5%8C%BA%E6%97%8F%22%5D%20--%3E%7C%22%E7%BA%A2%E9%98%9F%E6%A0%B7%E4%BE%8B%E7%A9%BF%E9%80%8F%22%7C%20A5%5B%22%E5%90%88%E6%B5%81%E5%AE%A1%E6%A0%B8%E5%9B%9E%E5%BD%92%E9%9B%86%E9%87%8D%E6%94%BE%22%5D%0A%20%20F6%5B%22%E5%8F%A3%E5%BE%84%E6%BC%82%E7%A7%BB%E6%97%8F%22%5D%20--%3E%7C%22%E7%A6%BB%E7%BA%BF%E4%B8%8E%E7%BA%BF%E4%B8%8A%E5%88%86%E6%95%B0%E8%83%8C%E7%A6%BB%22%7C%20A6%5B%22%E6%8C%89%E5%9B%9B%E9%92%89%E5%8D%8F%E8%AE%AE%E9%87%8D%E6%B5%8B%E5%AF%B9%E7%85%A7%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">一次典型的复合事故：预处理库升级使缓存键失效，旧嵌入继续命中，同时运营调低默认预算省成本——线上表现为「模型突然不识字」。单查预算或单查缓存都会得出错误结论，三跑判据是切开复合病因的刀。</span></p><p><span class="marginnote">三跑判据可以类比医生的鉴别诊断：先做三个便宜的血常规把「环境病」和「模型病」分开，而不是一上来就做昂贵的核磁（换模型、回滚训练）。花三次请求的成本，换来后续排查不跑偏——初学者容易一上来就怀疑模型本身，实际上多数「变笨」出在管线环境。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这门课收束的是<strong>服务侧</strong>：图像、视频、语音进入推理系统后怎么跑得对、快、省、稳。训练侧怎么造出更值得服务的模型——<a href="/llm/multimodal-rlhf">多模态 RLHF</a> 与<a href="/llm/multimodal-reasoning">多模态推理</a>的能力来源、生成侧的图像视频服务、基准的内部构造——各有其课，这里只接口。案例数字随模型与硬件过期，六族坐标与三跑判据跨代复用：管线还会更长，「静默变笨」只会更常见，归因坐标值得先于故障建好。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多模态失败的共同脾气是静默：不报错、只变笨、部分复现，必须靠族坐标排障。</li><li>六族：表示漂移、预算失衡、资源错配、时序违约、防线盲区、口径漂移，各配信号与第一动作。</li><li>三跑判据（冷、热、换预算）先切环境病与模型病；族是坐标，不是互斥判决。</li><li>监控按族建面板，告警直接落到第一诊断动作；面板先于故障建好。</li><li>服务侧课程至此收束：训练侧与生成侧各有其课，此处只接口。</li><li>出处：据本课程十二课小结与排障实践整理；文献口径见各课末条。</li></ul>',6))])}const u=n(p,[["render",F]]);export{c as __pageData,u as default};
